$ErrorActionPreference = "Stop"
$Utf8Bom = New-Object System.Text.UTF8Encoding($true)

function Find-ProjectRoot {
    $candidates = New-Object System.Collections.Generic.List[string]
    $candidates.Add($PSScriptRoot)
    $parent = Split-Path -Parent $PSScriptRoot
    if ($parent) { $candidates.Add($parent) }

    foreach ($candidate in $candidates) {
        if ((Test-Path (Join-Path $candidate "Assets\Resources\ScenarioV3.csv")) -and
            (Test-Path (Join-Path $candidate "ProjectSettings"))) {
            return (Resolve-Path $candidate).Path
        }
    }

    $children = @(Get-ChildItem -LiteralPath $PSScriptRoot -Directory -ErrorAction SilentlyContinue |
        Where-Object {
            (Test-Path (Join-Path $_.FullName "Assets\Resources\ScenarioV3.csv")) -and
            (Test-Path (Join-Path $_.FullName "ProjectSettings"))
        })
    if ($children.Count -eq 1) { return $children[0].FullName }
    throw "Unity 프로젝트 루트를 찾지 못했습니다. 이 파일들을 Assets와 ProjectSettings가 보이는 프로젝트 최상위 폴더에 두고 실행하세요."
}

function Get-FieldValue($row, [string]$name) {
    $prop = $row.PSObject.Properties[$name]
    if ($null -eq $prop -or $null -eq $prop.Value) { return "" }
    return [string]$prop.Value
}

function Set-FieldValue($row, [string]$name, [string]$value) {
    $prop = $row.PSObject.Properties[$name]
    if ($null -eq $prop) { throw "ScenarioV3.csv에 '$name' 열이 없습니다." }
    $prop.Value = $value
}

$ProjectRoot = Find-ProjectRoot
$ScenarioPath = Join-Path $ProjectRoot "Assets\Resources\ScenarioV3.csv"
$Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupDir = Join-Path $ProjectRoot "_Dobak_Text_Backup"
if (-not (Test-Path $BackupDir)) { New-Item -ItemType Directory -Path $BackupDir | Out-Null }
$BackupPath = Join-Path $BackupDir ("ScenarioV3.before_text_polish_" + $Timestamp + ".csv")
$ReportPath = Join-Path $ProjectRoot "ScenarioV3_TEXT_POLISH_REPORT.txt"

$PayloadBase64 = ''
$PayloadJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($PayloadBase64))
$Payload = $PayloadJson | ConvertFrom-Json
$TargetColumns = @($Payload.target_columns | ForEach-Object { [string]$_ })

$Rows = @(Import-Csv -LiteralPath $ScenarioPath)
if ($Rows.Count -eq 0) { throw "ScenarioV3.csv가 비어 있습니다." }
foreach ($required in @('line_id','text','choice_a_text','choice_b_text','choice_c_text')) {
    if ($null -eq $Rows[0].PSObject.Properties[$required]) {
        throw "ScenarioV3.csv에 필수 열 '$required'이 없습니다."
    }
}

$LineIdsBefore = @($Rows | ForEach-Object { [string]$_.line_id })
$DuplicateIds = @($LineIdsBefore | Where-Object { $_ } | Group-Object | Where-Object { $_.Count -gt 1 })
if ($DuplicateIds.Count -gt 0) { throw "line_id가 중복되어 안전하게 수정할 수 없습니다: $($DuplicateIds[0].Name)" }

$NonTargetColumns = @($Rows[0].PSObject.Properties.Name | Where-Object { $TargetColumns -notcontains $_ })
$NonTargetBefore = @()
foreach ($row in $Rows) {
    $snapshot = [ordered]@{}
    foreach ($column in $NonTargetColumns) { $snapshot[$column] = Get-FieldValue $row $column }
    $NonTargetBefore += ($snapshot | ConvertTo-Json -Compress)
}

Copy-Item -LiteralPath $ScenarioPath -Destination $BackupPath -Force
$Changed = New-Object System.Collections.Generic.List[string]
$Missing = New-Object System.Collections.Generic.List[string]

try {
    # Normalize money/point notation only in visible sentence fields.
    foreach ($row in $Rows) {
        foreach ($column in $TargetColumns) {
            $oldValue = Get-FieldValue $row $column
            $newValue = $oldValue
            foreach ($pair in $Payload.normalizations) {
                $from = [string]$pair[0]
                $to = [string]$pair[1]
                $newValue = $newValue.Replace($from, $to)
            }
            if ($newValue -ne $oldValue) {
                Set-FieldValue $row $column $newValue
                $Changed.Add("$($row.line_id) [$column]`r`n  이전: $oldValue`r`n  수정: $newValue")
            }
        }
    }

    # Apply reviewed, line-specific dialogue rewrites.
    foreach ($entry in $Payload.updates.PSObject.Properties) {
        $lineId = [string]$entry.Name
        $matches = @($Rows | Where-Object { [string]$_.line_id -eq $lineId })
        if ($matches.Count -eq 0) {
            $Missing.Add($lineId)
            continue
        }
        if ($matches.Count -ne 1) { throw "line_id '$lineId'가 $($matches.Count)개 있습니다." }
        $row = $matches[0]
        foreach ($field in $entry.Value.PSObject.Properties) {
            $column = [string]$field.Name
            if ($TargetColumns -notcontains $column) {
                throw "허용되지 않은 열을 수정하려 했습니다: $lineId / $column"
            }
            $oldValue = Get-FieldValue $row $column
            $newValue = [string]$field.Value
            if ($oldValue -ne $newValue) {
                Set-FieldValue $row $column $newValue
                $Changed.Add("$lineId [$column]`r`n  이전: $oldValue`r`n  수정: $newValue")
            }
        }
    }

    # Structural safety check before writing.
    if ($Rows.Count -ne $LineIdsBefore.Count) { throw "행 수가 변경되었습니다." }
    for ($i = 0; $i -lt $Rows.Count; $i++) {
        if ([string]$Rows[$i].line_id -ne $LineIdsBefore[$i]) {
            throw "행 순서 또는 line_id가 변경되었습니다: $i"
        }
        $snapshot = [ordered]@{}
        foreach ($column in $NonTargetColumns) { $snapshot[$column] = Get-FieldValue $Rows[$i] $column }
        $afterJson = $snapshot | ConvertTo-Json -Compress
        if ($afterJson -cne $NonTargetBefore[$i]) {
            throw "허용되지 않은 열이 변경되었습니다: $($Rows[$i].line_id)"
        }
    }

    $CsvLines = @($Rows | ConvertTo-Csv -NoTypeInformation)
    [IO.File]::WriteAllLines($ScenarioPath, [string[]]$CsvLines, $Utf8Bom)

    # Read back and verify again.
    $CheckRows = @(Import-Csv -LiteralPath $ScenarioPath)
    if ($CheckRows.Count -ne $Rows.Count) { throw "저장 후 행 수 검증에 실패했습니다." }
    for ($i = 0; $i -lt $CheckRows.Count; $i++) {
        if ([string]$CheckRows[$i].line_id -ne $LineIdsBefore[$i]) {
            throw "저장 후 line_id 순서 검증에 실패했습니다: $i"
        }
        foreach ($column in $NonTargetColumns) {
            if ((Get-FieldValue $CheckRows[$i] $column) -cne (Get-FieldValue $Rows[$i] $column)) {
                throw "저장 후 비문장 열 검증에 실패했습니다: $($Rows[$i].line_id) / $column"
            }
        }
    }

    $Report = New-Object System.Collections.Generic.List[string]
    $Report.Add("ScenarioV3 문체 수정 결과")
    $Report.Add("적용 시각: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')")
    $Report.Add("대상: $ScenarioPath")
    $Report.Add("백업: $BackupPath")
    $Report.Add("수정된 문장 칸 수: $($Changed.Count)")
    $Report.Add("현재 CSV에 없어 건너뛴 line_id 수: $($Missing.Count)")
    $Report.Add("")
    $Report.Add("[안전 검증]")
    $Report.Add("- 행 수 유지: PASS")
    $Report.Add("- 행 순서/line_id 유지: PASS")
    $Report.Add("- text 및 choice_*_text 외 모든 열 유지: PASS")
    $Report.Add("- C# / ScenarioV3Flow.csv / 씬 파일 미수정: PASS")
    $Report.Add("")
    if ($Missing.Count -gt 0) {
        $Report.Add("[현재 파일에 없어서 건너뛴 line_id]")
        foreach ($id in $Missing) { $Report.Add("- $id") }
        $Report.Add("")
    }
    $Report.Add("[변경 내역]")
    foreach ($item in $Changed) { $Report.Add($item); $Report.Add("") }
    [IO.File]::WriteAllLines($ReportPath, [string[]]$Report, $Utf8Bom)

    Write-Host "" 
    Write-Host "ScenarioV3 문체 수정 완료" -ForegroundColor Green
    Write-Host "수정된 문장 칸: $($Changed.Count)"
    Write-Host "백업 파일: $BackupPath"
    Write-Host "검증 보고서: $ReportPath"
    Write-Host "C#과 ScenarioV3Flow.csv는 수정하지 않았습니다." -ForegroundColor Cyan
}
catch {
    Copy-Item -LiteralPath $BackupPath -Destination $ScenarioPath -Force
    Write-Host "" 
    Write-Host "적용 중 오류가 발생해 원본 CSV를 복원했습니다." -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    throw
}
